			if ((x > 0) && (twoMat.at<uchar>(y, x - 1) == 0)) {
				outMat.at<uchar>(y, x) = 0;
				continue;
			}
			if ((y > 0) && (twoMat.at<uchar>(y - 1, x) == 0)) {
				outMat.at<uchar>(y, x) = 0;
				continue;
			}
			if ((x < width - 1) && (twoMat.at<uchar>(y, x + 1) == 0)) {
				outMat.at<uchar>(y, x) = 0;
				continue;
			}
			if ((x > 0) && (twoMat.at<uchar>(y + 1, x) == 0)) {
				outMat.at<uchar>(y, x) = 0;
				continue;
			}
		}
	}
	return outMat;

